    const n = nums.length;
    if (n <= 1) return 0;

    const val = nums.map(x => BigInt(x));
    const prev = new Int32Array(n);
    const next = new Int32Array(n);
    const deleted = new Uint8Array(n);
    const version = new Int32Array(n);

