        prev[i] = i - 1;
        next[i] = i + 1 < n ? i + 1 : -1;
    }

    let descents = 0;
    for (let i = 0; i < n - 1; i++) {
        if (val[i] > val[i + 1]) descents++;
    }

    if (descents === 0) return 0;

    const pq = new MinHeap();
    for (let i = 0; i < n - 1; i++) {
        pq.push({ sum: val[i] + val[i + 1], id: i, ver: 0 });
    }

    let ops = 0;
    while (descents > 0 && pq.size() > 0) {
        const top = pq.pop();
        const u = top.id;

        if (deleted[u] || top.ver !== version[u]) continue;
        const v = next[u];
